s=registration_context().settings
def get(path):return request_local_pa(s,'GET',path,timeout_seconds=7)
def build():
 b=get('/api/status')['runtime_build']
 assert b['source_revision']=='17a060185f37b10f643a6027f826a14617827974'
 assert b['package_identity']==json.loads(Path('.dev/pr515-installed-package-identity.json').read_text())['package_identity']
 return b
before=build();runtime=get('/api/runtime');omitted=[]
DROP={'detail','message','sanitized_signature','metadata','prompt','prompts','answer','answers','payload','body','operator_input','permission_response','decisions','recovery'}
STRINGS={'name','kind','sandbox_profile','last_success_at','endpoint_type','operation','phase','state','classification','retry_state','type','session_id','provider_id','profile','id','endpoint','direction','client_id','peer_id','session_scope','paired_id','opened_at','last_success','last_failure','last_probe_at','last_failure_at','last_successful_poll_at','started_at','finished_at','measured_at','measurement_state','journal_mode','integrity','migration','redaction_policy','observation_scope','scope','lock_note','lock_events_note','window','method','path','correlation_id'}
def sanitize(value,path=()):
 if value is None or isinstance(value,(bool,int,float)):return value
 if isinstance(value,list):return [sanitize(v,(*path,str(i))) for i,v in enumerate(value)]
 if isinstance(value,dict):
  out={}
  for key,v in value.items():
   if key in DROP:
    omitted.append('.'.join((*path,key)));continue
   out[key]=sanitize(v,(*path,key))
  return out
 if isinstance(value,str) and path and path[-1] in STRINGS:
  # These fields have a documented metadata role. Opaque failure/prompt text
  # above is never retained; URI credentials and known tokens are also masked.
  value=re.sub(r'(?i)(https?://)[^\s/@]+:[^\s/@]+@',r'\1[REDACTED]@',value)
  value=re.sub(r'\b(?:sk|gh[oprsu]|xox[abprs])-[-A-Za-z0-9_]{8,}\b','[REDACTED]',value)
  return value[:500]
 omitted.append('.'.join(path));return {'omitted_opaque_type':type(value).__name__}
