out={'observed_at':datetime.now(UTC).isoformat(),'runtime_build':before,'build_stable':True,
 'scope':'New17a capture uses corrected full-section schema. Every earlier snapshot and its irrecoverable gaps remain separate. Knownmetadata identifiers retained; opaqueerror/metadata/privatevalues stillomitted. This snapshot cannot recover discarded older auxiliary data or be combined with the sequential GET sample window as a single observation. Allreturnedtop-levelsections retained withopaqueerror/metadata/prompt text omitted; omissionpaths explicit. No write/provider/peer/backup/fault/workload injection.',
 'received_top_level_keys':list(runtime),'omitted_opaque_paths':omitted,'runtime':clean}
raw=json.dumps(out,indent=2)+'\n';sha=hashlib.sha256(raw.encode()).hexdigest();p=Path('.dev/17a-runtime-sections-complete.json');assert not p.exists();p.with_name(p.stem+'.'+sha+'.json').write_text(raw);p.write_text(raw)
aux=clean.get('diagnostics_executor',{});print(json.dumps({'sha256':sha,'received_sections':list(runtime),'primary_operations':len(clean.get('operations',{})),'diagnostic_operations':len(aux.get('operations',{})),'omitted_opaque_count':len(omitted),'runtime_build':before}))

